      c: "all",
      s: "all",
      n: "all",
      r0: 0,
      r1: MAX_BALANCE_USD,
    });

    setCurrentPage(1);
    setTasksPage(1);
    setSelectedRowKeys([]);
    setSelectedRows([]);

    await Promise.all([
      fetchStats(),
