type Web3UserResp = {
  user?: Web3UserDetail;
};

type TxItem = {
  id?: string;
  tx_hash?: string;
  network?: string;
  chain_id?: string;
  user_address?: string;
  tx_type?: string;
  direction?: string;
  asset_code?: string;
  amount?: string;
  amount_usd?: string;
  from_address?: string;
  to_address?: string;
  status?: string;
  confirmations?: number;
  fee?: string;
  fee_asset?: string;
  block_number?: string;
  block_time?: string;
  created_at?: string;
