import { PageContainer } from '@ant-design/pro-components';
import { FundsOverview } from '@/components';
import { createStyles } from 'antd-style';
import { useIntl } from '@umijs/max';
import React, { useState, useCallback, useEffect, useMemo } from 'react';
import {
  WalletOutlined,
  SyncOutlined,
  WarningOutlined,
  CheckCircleOutlined,
  PlusOutlined,
  SettingOutlined,
  RightOutlined,
  DownOutlined,
  DeleteOutlined,
} from '@ant-design/icons';
import {
  Button,
  Tag,
  Typography,
  Space,
  App,
  Pagination,
  Modal,
  Form,
  Input,
  Select,
  Alert,
  InputNumber,
  Spin,
} from 'antd';
import { SaveOutlined } from '@ant-design/icons';
import {
  adminGetVaultOverview,
  adminListVaultAddresses,
  adminGetVaultAddressBalances,
  adminAddVaultAddress,
  adminUpdateVaultAddressStatus,
  adminDeleteVaultAddress,
  adminUpdateVaultThresholds,
  adminSyncVault,
} from '@/api/generated/vault';
import type {
  AdminVaultNetworkOverviewItem,
  AdminVaultAddressItem,
  AdminVaultAddressBalanceItem,
  AdminAddVaultAddressRequest,
  AdminVaultBalanceOverviewItem,
} from '@/api/generated/schemas';
import { useRbac } from '@/hooks/useRbac';

const { Text } = Typography;

const PERM = {
  overview: 'GetVaultOverview',
  list: 'ListVaultAddresses',
  create: 'AddVaultAddress',
  updateStatus: 'UpdateVaultAddressStatus',
  remove: 'DeleteVaultAddress',
  balances: 'GetVaultAddressBalances',
  thresholds: 'UpdateVaultThresholds',
  sync: 'SyncVault',
};

// Wallet type options
const walletTypeOptions = [
  { value: 'active', label: '活跃钱包' },
  { value: 'hot', label: '热钱包' },
  { value: 'cold', label: '冷钱包' },
];

// Type for UI display - transformed from API data
interface UIWallet {
  id: string;
  type: string;
  label: string;
  address: string;
  addedAt: string;
  isActive: boolean;
  currencies: UICurrency[];
  networkId: string;
}

interface UICurrency {
  symbol: string;
  balance: number;
  balanceUsdt: number;
  threshold?: number;
  thresholdCritical?: number;
  status: 'normal' | 'warning' | 'critical';
  contractAddress?: string;
}

interface UINetwork {
  id: string;
  networkId: string;
  chainId: string;
  name: string;
  currencyCount: number;
  totalValueUsdt: number;
  hasAlert: boolean;
  alertCount: number;
  color: string;
  wallets: UIWallet[];
  inactiveWallets: { id: string; address: string; addedAt: string }[];
  lastSyncAt?: string;
  syncStatus?: string;
  // Threshold data from overview
  thresholds: Map<string, { low: string; critical: string }>;
}

// Type for editing state
interface EditingCurrency {
  networkId: string;
  walletId: string;
  symbol: string;
  low: number | null;
  critical: number | null;
}

const useStyles = createStyles(({ token }) => ({
  page: {
    position: 'relative',
  },
  // Management Section
  managementSection: {
    borderRadius: 16,
    background: '#fff',
    border: '1px solid #f0f0f0',
    boxShadow: '0 4px 20px rgba(0, 0, 0, 0.04)',
    overflow: 'hidden',
  },
  managementHeader: {
    padding: '24px 32px',
    borderBottom: '1px solid #f0f0f0',
  },
  managementTitle: {
    fontSize: 20,
    fontWeight: 700,
    color: '#1f2937',
    marginBottom: 4,
  },
  managementSubtitle: {
    fontSize: 14,
    color: '#9ca3af',
  },
  managementStats: {
    display: 'flex',
    alignItems: 'center',
    gap: 32,
    marginTop: 20,
    padding: 20,
    borderRadius: 12,
    background: 'linear-gradient(135deg, #ecfdf5 0%, #d1fae5 100%)',
  },
  managementStatItem: {
    display: 'flex',
    flexDirection: 'column',
    gap: 4,
    paddingRight: 32,
    borderRight: '1px solid rgba(16, 185, 129, 0.2)',
    '&:last-child': {
      borderRight: 'none',
      paddingRight: 0,
    },
  },
  managementStatLabel: {
    fontSize: 13,
    color: '#059669',
  },
  managementStatValue: {
    fontSize: 24,
    fontWeight: 700,
    fontFamily: '"DIN Alternate", "Bebas Neue", "Teko", sans-serif',
    color: '#10b981',
  },
  managementActions: {
    display: 'flex',
    alignItems: 'center',
    gap: 12,
    marginTop: 20,
  },
  managementMeta: {
    marginTop: 10,
    display: 'flex',
    alignItems: 'center',
    gap: 16,
    flexWrap: 'wrap',
    color: '#6b7280',
    fontSize: 12,
  },
  managementMetaItem: {
    display: 'flex',
    alignItems: 'center',
    gap: 6,
  },
  // Table Section
  tableSection: {
    padding: '0 32px 32px',
  },
  tableHeader: {
    display: 'grid',
    gridTemplateColumns: '180px 200px 120px 100px 100px',
    padding: '16px 20px',
    background: '#f9fafb',
    borderRadius: '12px 12px 0 0',
    borderBottom: '1px solid #e5e7eb',
    gap: 16,
  },
  tableHeaderCell: {
    fontSize: 13,
    fontWeight: 600,
    color: '#6b7280',
  },
  paginationBar: {
    display: 'flex',
    justifyContent: 'flex-end',
    padding: '12px 0 16px',
  },
  networkGroup: {
    marginBottom: 8,
    borderRadius: 12,
    border: '1px solid #e5e7eb',
    overflow: 'hidden',
    '&:last-child': {
      marginBottom: 0,
    },
  },
  networkGroupHeader: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
